47: export const sendNotification = function (challenge: ChallengeModel, isRestore: boolean) {
48:   if (notSolved(challenge)) {
49:     return
50:   }
51: 
52:   const flag = utils.ctfFlag(challenge.name)
53: 
54:   const challengeKey = challenge.key as ChallengeKey
55:   const fullChallenge = challenges[challengeKey]
56: 
57:   let hasCodingChallenge = false
58:   if (fullChallenge) {
59:     hasCodingChallenge = Boolean(fullChallenge.hasCodingChallenge) ?? false
60:   }
61: 
62:   const notification = {
63:     key: challenge.key,
64:     name: challenge.name,
65:     challenge: challenge.name + ' (' + entities.decode(sanitizeHtml(challenge.description, { allowedTags: [], allowedAttributes: {} })) + ')',
66:     flag,
67:     hidden: !config.get('challenges.showSolvedNotifications'),
68:     isRestore,
69:     codingChallenge: config.get('challenges.codingChallengesEnabled') !== 'never' && hasCodingChallenge
70:   }
71:   const wasPreviouslyShown = notifications.some(({ key }) => key === challenge.key)
72:   notifications.push(notification)
73: 
74:   if (globalWithSocketIO.io && (isRestore || !wasPreviouslyShown)) {
75:     globalWithSocketIO.io.emit('challenge solved', notification)
76:   }
77: }
